sys_script_include.script:
/** @type {MarkdownGenerationContextConstructor} */
var MarkdownGenerationContext = (function() {
    var instanceUri = gs.getProperty('glide.servlet.uri');

    /** @type {MarkdownGenerationContextConstructor} */
    var MarkdownGenerationContextConstructor = Class.create();

    /**
     * @param {string} [path]
     * @return {string}
     */
    function getInstanceUrl(path) {
        if (gs.nil(path))
            return instanceUri;
        var p = '' + path;
        while (p.startsWith('/') || p.startsWith('\\'))
            p = p.substring(1);
        return instanceUri + p;
    }

    MarkdownGenerationContextConstructor.getInstanceUrl = getInstanceUrl;

    var markdownReservedRe = /[\\`*[\]()]/g;
    var markdownLeadReservedRe = /^[#|]/;
    var markdownTableReservedRe = /[\\`*[\]()|]/g;
    var newLineRe = /\r\n|\n/g;
    var abnormalWsRe = / \s+|(?! )\s+/g;
    var codeBlockReqRe = /[(?:\r\n|\n)`]/g;

    /**
     * @param {string} text
     * @param {boolean} [isTableCellContent]
     * @returns {string}
     */
    function escapeForMarkdown(text, isTableCellContent) {
        return gs.nil(text) ? '' : isTableCellContent ? text.replace(markdownTableReservedRe, '\\$&') : text.replace(markdownReservedRe, '\\$&').replace(markdownLeadReservedRe, '\\$&');
    }

    MarkdownGenerationContextConstructor.escapeForMarkdown = escapeForMarkdown;

    /**
     * @param {string} text
     * @returns {string}
     */
    function normalizeWhiteSpace(text) {
        return gs.nil(text) ? '' : ('' + text).replace(abnormalWsRe, ' ').trim();
    }

    MarkdownGenerationContextConstructor.normalizeWhiteSpace = normalizeWhiteSpace;

    MarkdownGenerationContextConstructor.prototype = {
        mapper: null,
        _current_folder: '',

        initialize: function() {
            this.mapper = new ReferenceLinkMapper();
        },

        getCurrentFolder: function() {
            return this._current_folder;
        },

        setCurrentFolder: function(folder) {
            this._current_folder = ('' + folder);
        },

        getTableReferenceMdLink: function(glideElement, isForTableCell) {
            return this.mapper.getTableMdLink(glideElement, this._current_folder, isForTableCell);
        },

        getColumnReferenceMdLink: function(tableElement, columnElement, isForTableCell) {
            return this.mapper.getColumnMarkdownLink(tableElement, columnElement, this._current_folder, isForTableCell);
        },

        getCatItemReferenceMdLink: function(glideElement, isForTableCell) {
            return this.mapper.getCatItemMdLink(glideElement, this._current_folder, isForTableCell);
        },

        getFlowReferenceMdLink: function(glideElement, isForTableCell) {
            return this.mapper.getFlowMdLink(glideElement, this._current_folder, isForTableCell);
        },

        getVarSetReferenceMdLink: function(glideElement, isForTableCell) {
            return this.mapper.getVarSetMdLink(glideElement, this._current_folder, isForTableCell);
        },

        pushTableReferenceListItem: function(glideElement, markdownLines, showEmpty) {
            if (gs.nil(glideElement)) {
                if (showEmpty)
                    markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(glideElement.getLabel()) + ':** *Empty*');
            } else
                markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(glideElement.getLabel()) + ':** ' + this.mapper.getTableMdLink(glideElement.getValue(), this._current_folder));
        },

        pushFieldReferenceListItem: function(tableElement, fieldElement, markdownLines, showEmpty) {
            if (gs.nil(fieldElement)) {
                if (showEmpty)
                    markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(fieldElement.getLabel()) + ':** *Empty*');
            } else
                markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(fieldElement.getLabel()) + ':** ' + this.mapper.getColumnMdLink(tableElement, fieldElement, this._current_folder));
        },

        pushCatItemReferenceListItem: function(glideElement, markdownLines, showEmpty) {
            if (gs.nil(glideElement)) {
                if (showEmpty)
                    markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(glideElement.getLabel()) + ':** *Empty*');
            } else
                markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(glideElement.getLabel()) + ':** ' + this.mapper.getCatItemMdLink(glideElement.getValue(), this._current_folder));
        },

        pushFlowReferenceListItem: function(glideElement, markdownLines, showEmpty) {
            if (gs.nil(glideElement)) {
                if (showEmpty)
                    markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(glideElement.getLabel()) + ':** *Empty*');
            } else
                markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(glideElement.getLabel()) + ':** ' + this.mapper.getFlowMdLink(glideElement.getValue(), this._current_folder));
        },

        pushVarSetReferenceListItem: function(glideElement, markdownLines, showEmpty) {
            if (gs.nil(glideElement)) {
                if (showEmpty)
                    markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(glideElement.getLabel()) + ':** *Empty*');
            } else
                markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(glideElement.getLabel()) + ':** ' + this.mapper.getVarSetMdLink(glideElement.getValue(), this._current_folder));
        },

        pushDisplayValueListItem: function(glideElement, markdownLines, multiLineStack, showEmpty) {
            if (gs.nil(glideElement)) {
                if (showEmpty)
                    markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(glideElement.getLabel()) + ':** *Empty*');
            } else {
                var value = glideElement.getDisplayValue();
                if (newLineRe.test(value))
                    multiLineStack.push({
                        label: glideElement.getLabel(),
                        language: 'text',
                        value: value
                    });
                else
                    markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(glideElement.getLabel()) + ':** ' + MarkdownGenerationContext.escapeForMarkdown(value));
            }
        },

        pushValueListItem: function(glideElement, markdownLines, multiLineStack, showEmpty) {
            if (gs.nil(glideElement)) {
                if (showEmpty)
                    markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(glideElement.getLabel()) + ':** *Empty*');
            } else {
                var value = glideElement.getValue();
                if (newLineRe.test(value))
                    multiLineStack.push({
                        label: glideElement.getLabel(),
                        language: 'text',
                        value: value
                    });
                else
                    markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(glideElement.getLabel()) + ':** ' + MarkdownGenerationContext.escapeForMarkdown(value));
            }
        },

        pushCodeListItem: function(glideElement, language, markdownLines, multiLineStack, showEmpty) {
            if (gs.nil(glideElement)) {
                if (showEmpty)
                    markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(glideElement.getLabel()) + ':** *Empty*');
            } else {
                var value = glideElement.getValue();
                if (newLineRe.test(value))
                    multiLineStack.push({
                        label: glideElement.getLabel(),
                        language: language,
                        value: value
                    });
                else
                    markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(glideElement.getLabel()) + ':** `' + value + '`');
            }
        },

        pushBoolean: function(glideElement, markdownLines, showEmpty) {
            if (gs.nil(glideElement)) {
                if (showEmpty)
                    markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(glideElement.getLabel()) + ':** *Empty*');
            } else {
                var value = glideElement.getDisplayValue();
                switch (value) {
                    case 'true':
                        value = 'True';
                        break;
                    case 'false':
                        value = 'False';
                        break;
                    default:
                        value = MarkdownGenerationContext.escapeForMarkdown(value);
                        berak;
                }
                markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(glideElement.getLabel()) + ':** ' + value);
            }
        },

        pushListItemIfTrue: function(glideElement, markdownLines) {
            if (!gs.nil(glideElement) && glideElement.getDisplayValue() == 'true')
                markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(glideElement.getLabel()) + ':** True');
        },

        pushListItemIfFalse: function(glideElement, markdownLines, nilIsFalse) {
            if (gs.nil(glideElement) ? nilIsFalse : glideElement.getDisplayValue() == 'false')
                markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(glideElement.getLabel()) + ':** False');
        },

        pushImageListItem: function(glideElement, markdownLines, showEmpty) {
            if (gs.nil(glideElement)) {
                if (showEmpty)
                    markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(glideElement.getLabel()) + ':** *Empty*');
            } else {
                var attachmentGr = new GlideRecord('sys_attachment');
                if (attachmentGr.get(glideElement.getValue())) {
                    var remoteFileName = glideElement.getDisplayValue();
                    var fileName = remoteFileName;
                    var content_type = attachmentGr.getValue('content_type');
                    var m;
                    switch (content_type) {
                        case 'image/png':
                            m = fileName.match(iixExtensionRe);
                            if (m)
                                fileName = m[1] + '.jpg';
                            break;
                        case 'image/jpeg':
                            m = fileName.match(iixExtensionRe);
                            if (m)
                                fileName = m[1] + '.png';
                            break;
                        default:
                            fileName = fileName + '; ' + content_type;
                            break;
                    }
                    markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(glideElement.getLabel()) + ':** ![' + MarkdownGenerationContext.escapeForMarkdown(fileName) + '](' + instanceUri + remoteFileName + ')');
                } else
                    markdownLines.push('- **' + MarkdownGenerationContext.escapeForMarkdown(glideElement.getLabel()) + ':** ' + MarkdownGenerationContext.escapeForMarkdown(glideElement.getDisplayValue()));
            }
        },

        pushMultiLineItems: function(multiLineStack, markdownLines) {
            for (var i = 0; i < multiLineStack.length; i++) {
                /** @type {LabeledMultilineStackItem} */
                var mi = multiLineStack[i];
                markdownLines.push('', '**' + mi.label + ':**', '', '```' + mi.language, mi.value, '```');
            }
        },

        type: 'MarkdownGenerationContext'
    };

    return MarkdownGenerationContextConstructor;
})();
